$out = foreach ($d in $dirs) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*') { continue }
  $p = $d.FullName
  if (-not (Test-Path "$p\.git")) {
    # Football and SpecialRequests are grouping folders, not projects
    if ($p -eq "$root\Football" -or $p -eq "$root\SpecialRequests") { continue }
    [pscustomobject]@{Name=$d.Name; Path=$p; Kind='not-a-repo'; Dirty=''; Ahead=''; Behind=''}; continue
  }
  $remote = git -C $p remote get-url origin 2>$null
  if (-not $remote) { [pscustomobject]@{Name=$d.Name; Path=$p; Kind='no-remote'; Dirty=''; Ahead=''; Behind=''}; continue }
