  git -C $p fetch -q origin 2>$null
  $ab = git -C $p rev-list --left-right --count 'HEAD...@{u}' 2>$null
  $a,$b = if ($ab) { $ab -split '\s+' } else { '?','?' }
  [pscustomobject]@{Name=$d.Name; Path=$p; Kind=($(if ($remote -match 'erash11') {'ok'} else {"other:$remote"})); Dirty=$dirty; Ahead=$a; Behind=$b}
}
$out | Export-Csv "$PSScriptRoot\inv.csv" -NoTypeInformation
"repos: $(@($out).Count)"
