class _Server(http.server.HTTPServer):
    # On Windows SO_REUSEADDR lets a second server share a port already in use, so a
    # taken 7474 would go unnoticed. Elsewhere it only skips TIME_WAIT, which we want.
    allow_reuse_address = os.name != "nt"


def bind(repo: Path, token: str, port: int, dev_root: Path | None = None) -> http.server.HTTPServer:
    """The requested port, or any free one if something else holds it."""
    try:
        return make_server(repo, token, port, dev_root)
    except OSError:
        if not port:
            raise
        print(f"port {port} is taken; using a free one (the Dock app's URL won't match this run)")
        return make_server(repo, token, 0, dev_root)


def token_path() -> Path:
    override = os.environ.get("PM_BOARD_TOKEN")
    if override:
        return Path(override)
    base = Path(os.environ["LOCALAPPDATA"]) if os.name == "nt" else Path.home() / ".config"
    return base / "pm-board" / "token"


def load_token(path: Path) -> str:
    """The machine's board token: made once, then reused so the board's URL stays put."""
    try:
        tok = path.read_text(encoding="utf-8").strip()
        if tok:
            return tok
    except OSError:
        pass
    path.parent.mkdir(parents=True, exist_ok=True)
    tok = secrets.token_urlsafe(16)
    path.write_text(tok, encoding="utf-8")
    try:
        path.chmod(0o600)
    except OSError:
        pass
    return tok


# ---------- one board per machine

